package org.slavicmyths.client;
import java.util.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.components.Button;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.ItemStack;
import org.slavicmyths.wolf.*;
import org.slavicmyths.military.GreyWolfStory;
/** Native widgets, server snapshots and live old wolf renderer; compact layout retains native font. */
public final class WolfStoryScreen extends Screen {
 private CompoundTag data;private int selected,page,objectiveScroll,railScroll;private boolean pending;private long sentAt;private int panelW,panelH,rightX;private double scale;private int ox,oy;private boolean compact;private List<net.minecraft.util.FormattedCharSequence> dialog=List.of();private String notice="";
 public WolfStoryScreen(CompoundTag d){super(Component.translatable("entity.slavicmyths.grey_wolf"));data=d.copy();}
 private CompoundTag q(){return data.getList("Quests",10).getCompound(selected);}private String stage(){return q().getString("State");}
 private Component t(String key,Object...args){return GreyWolfStory.text(key,args);}
 public void update(CompoundTag d){data=d.copy();pending=false;if(d.getInt("Action")==1){notice="ask."+selected;page=0;}else if(d.getInt("Action")==2){notice="claimed."+selected;page=0;}else if(d.getInt("Action")==4){notice="handed."+selected;page=0;}else if(d.getInt("Action")==0){notice="accepted."+selected;page=0;}else if(d.getInt("Action")==-1)notice="rejected";refresh();}
 @Override protected void init(){compact=width<420||height<230;panelW=compact?310:408;panelH=compact?Math.max(150,Math.min(218,height-12)):218;rightX=compact?125:223;scale=Math.min(1,Math.min((width-12.0)/panelW,(height-12.0)/panelH));ox=(int)((width-panelW*scale)/2);oy=(int)((height-panelH*scale)/2);refresh();addRenderableWidget(Button.builder(org.slavicmyths.quest185.Quest185Story.text("chapter"),b->Quest185Screen.request()).bounds(ox,Math.max(0,oy-21),(int)(panelW*scale),18).build());}
 private void refresh(){clearWidgets();if(font==null)return;int rows=Math.min(4,Math.max(1,(panelH-53)/32));railScroll=Math.clamp(railScroll,Math.max(0,selected-rows+1),Math.min(selected,4-rows));for(int i=railScroll;i<railScroll+rows;i++){final int index=i;var b=new Row(13,44+(i-railScroll)*32,104,30,index);addRenderableWidget(b);}int y=panelH-27;String state=stage();if(state.equals("OFFERED")){button(rightX,y,60,"accept",0);button(rightX+64,y,66,"ask",1);button(rightX+134,y,42,"leave",-1);}else if(state.equals("REWARD_READY")){button(rightX,y,72,"claim",2);button(rightX+76,y,60,"ask",1);button(rightX+140,y,36,"leave",-1);}else if(state.equals("ACTIVE")){if(selected==3&&q().getString("Phase").equals("RETURN"))button(rightX,y,80,"hand_over",4);else button(rightX,y,80,"track",3);button(rightX+84,y,52,"reward",1);button(rightX+140,y,36,"leave",-1);}else {var b=button(rightX,y,100,state.equals("COMPLETED")?"claimed":"locked",-2);b.active=false;button(rightX+134,y,42,"leave",-1);}var dialogue=selected==3&&notice.equals("accepted.3")&&q().contains("Clue")?acceptedClue():notice.isEmpty()?t("dialog."+selected+"."+(state.equals("REWARD_READY")&&!q().getBoolean("Known")?"ready_unknown":selected==3&&state.equals("ACTIVE")?q().getString("Phase").toLowerCase():state.toLowerCase()),q().getInt("Progress")):t("dialog."+notice);dialog=font.split(dialogue,164);}
 private Component acceptedClue(){var pos=net.minecraft.core.BlockPos.of(q().getLong("Clue"));return t("dialog.accepted.3",t("direction."+q().getString("Direction")),pos.getX(),pos.getZ());}
 private Button button(int x,int y,int w,String label,int action){var b=new ActionButton(x,y,w,label,action);b.active=!pending;return addRenderableWidget(b);}
 private void send(int action){if(pending||!data.hasUUID("Wolf")||!data.hasUUID("Nonce"))return;pending=true;sentAt=net.minecraft.Util.getMillis();for(var widget:children())if(widget instanceof Button b)b.active=false;net.neoforged.neoforge.network.PacketDistributor.sendToServer(new WolfStoryNetwork.Action(data.getUUID("Wolf"),data.getUUID("Nonce"),selected,action));}
 @Override public void tick(){if(pending&&net.minecraft.Util.getMillis()-sentAt>5000){pending=false;notice="waiting";refresh();}if(minecraft.level==null||minecraft.player==null){onClose();return;}var actor=minecraft.level.getEntity(data.getInt("Entity"));if(actor==null||!actor.isAlive()||minecraft.player.distanceToSqr(actor)>100)onClose();}
 private static ResourceLocation asset(String name){return ResourceLocation.fromNamespaceAndPath("slavicmyths","textures/gui/grey_wolf/"+name+".png");}
 private void image(GuiGraphics g,String name,int x,int y,int w,int h,int sw,int sh){g.blit(asset(name),x,y,w,h,0,0,sw,sh,sw,sh);}
 private void plate(GuiGraphics g,int x,int y,int w,int h){int[] sx={0,4,28},sy={0,4,28},sizes={4,24,4},dx={x,x+4,x+w-4},dy={y,y+4,y+h-4},dw={4,w-8,4},dh={4,h-8,4};for(int a=0;a<3;a++)for(int b=0;b<3;b++)g.blit(asset("frame"),dx[a],dy[b],dw[a],dh[b],sx[a],sy[b],sizes[a],sizes[b],32,32);}
 private void parchment(GuiGraphics g,int x,int y,int w,int h){image(g,"parchment",x,y,w,h,32,32);}
 private void lines(GuiGraphics g,Component c,int x,int y,int w,int limit,int color){var list=font.split(c,w);for(int i=0;i<Math.min(limit,list.size());i++)g.drawString(font,list.get(i),x,y+i*9,color,false);}
 @Override public void render(GuiGraphics g,int mx,int my,float delta){g.fill(0,0,width,height,0xA6000000);int x=(int)((mx-ox)/scale),y=(int)((my-oy)/scale);g.pose().pushPose();g.pose().translate(ox,oy,0);g.pose().scale((float)scale,(float)scale,1);plate(g,0,0,panelW,panelH);image(g,"paw",10,8,8,8,8,8);g.drawString(font,title,22,8,0xDDD0AD,false);g.fill(9,25,121,panelH-9,0xFF2C2E32);g.drawCenteredString(font,t("quests"),65,30,0xDDD0AD);
  if(!compact){image(g,"forest",125,25,94,153,96,160);var entity=minecraft.level.getEntity(data.getInt("Entity"));if(entity instanceof GreyWolf wolf)net.minecraft.client.gui.screens.inventory.InventoryScreen.renderEntityInInventoryFollowsAngle(g,128,28,216,175,45,.55F,1.65F,-.08F,wolf);parchment(g,125,181,94,28);g.drawCenteredString(font,title,172,185,0x2D2924);lines(g,t("subtitle"),129,195,86,1,0x6B5841);}
  int dialogueH=compact?44:54;parchment(g,rightX,25,176,dialogueH);int perPage=compact?3:4,maxPage=Math.max(0,(dialog.size()-1)/perPage);page=Math.clamp(page,0,maxPage);for(int n=0;n<perPage&&page*perPage+n<dialog.size();n++)g.drawString(font,dialog.get(page*perPage+n),rightX+6,31+n*9,0x2D2924,false);if(maxPage>0)g.drawString(font,Component.literal((page+1)+"/"+(maxPage+1)+" >"),rightX+130,25+dialogueH-9,0x6B5841,false);
  int top=compact?73:83,bottom=panelH-31;parchment(g,rightX,top,117,bottom-top);parchment(g,rightX+121,top,55,bottom-top);int objectiveTop=top+(selected==3?24:0);if(selected==3){var phases=List.of("TRACK","FIGHT","FIND_CURSE","EXCAVATE","RETURN");int current=phases.indexOf(q().getString("Phase"));if(current<0)current=5;for(int step=0;step<5;step++){image(g,"volkolak_objective_"+step,rightX+7+step*21,top+4,16,16,32,32);if(step==current)g.renderOutline(rightX+6+step*21,top+3,18,18,0xFFB9A16C);else if(step<current)g.renderOutline(rightX+6+step*21,top+3,18,18,0xFF698868);}}g.enableScissor(rightX+4,objectiveTop+3,rightX+113,bottom-6);var text=new ArrayList<net.minecraft.util.FormattedCharSequence>();text.addAll(font.split(t("title."+selected),105));text.addAll(font.split(objective(),105));if(q().contains("Clue")){var pos=net.minecraft.core.BlockPos.of(q().getLong("Clue"));text.addAll(font.split(t("clue",pos.getX(),pos.getZ()),105));}int visible=Math.max(1,(bottom-objectiveTop-14)/9);objectiveScroll=Math.clamp(objectiveScroll,0,Math.max(0,text.size()-visible));for(int n=0;n<visible&&n+objectiveScroll<text.size();n++)g.drawString(font,text.get(n+objectiveScroll),rightX+6,objectiveTop+5+n*9,0x2D2924,false);g.disableScissor();if(selected==0){int value=q().getInt("Progress");g.fill(rightX+8,bottom-6,rightX+109,bottom-3,0xFF464A51);g.fill(rightX+9,bottom-5,rightX+9+99*value/15,bottom-4,value==15?0xFF698868:0xFFB9A16C);}g.drawCenteredString(font,t("reward"),rightX+148,top+5,0x2D2924);
  int slotY=top+(compact?16:24);if(!q().getBoolean("Known")){image(g,"reward_slot",rightX+131,slotY,34,34,34,34);g.drawCenteredString(font,Component.literal("?"),rightX+148,slotY+12,0xAAA9A1);}else{var rewards=q().getList("Rewards",10);for(int n=0;n<rewards.size();n++){var item=ItemStack.parseOptional(minecraft.level.registryAccess(),rewards.getCompound(n));int sy=slotY+(compact?0:n*23),sx=rightX+(compact&&rewards.size()>1?126+n*23:138);image(g,"reward_slot",sx,sy,20,20,34,34);g.renderItem(item,sx+2,sy+2);g.renderItemDecorations(font,item,sx+2,sy+2);if(x>=sx&&x<sx+20&&y>=sy&&y<sy+20)g.renderTooltip(font,selected==1&&n==1&&!stage().equals("COMPLETED")?t("random_rune"):item.getHoverName(),x,y);}}
  super.render(g,x,y,delta);g.pose().popPose();}
 private Component objective(){if(selected==0)return t("objective.0",q().getInt("Progress"));if(selected==1)return t(q().getBoolean("HasTarget")?"objective.1.tier":"objective.1.search",q().getInt("Tier"));if(selected==2)return t(q().getBoolean("HasTarget")?"objective.2":"target_missing");return t("objective.3."+q().getString("Phase").toLowerCase());}
 private void turn(int amount){page+=amount;net.minecraft.client.Minecraft.getInstance().getSoundManager().play(net.minecraft.client.resources.sounds.SimpleSoundInstance.forUI(org.slavicmyths.finist.FinistSounds.get("dialog_page"),1,.4F));}
 @Override public boolean mouseClicked(double mx,double my,int button){double x=(mx-ox)/scale,y=(my-oy)/scale;if(x>=rightX+130&&x<rightX+176&&y>=55&&y<79){turn(1);return true;}return super.mouseClicked(x,y,button);}
 @Override public boolean mouseReleased(double mx,double my,int b){return super.mouseReleased((mx-ox)/scale,(my-oy)/scale,b);}
 @Override public boolean mouseScrolled(double mx,double my,double dx,double dy){double x=(mx-ox)/scale,y=(my-oy)/scale;if(x<0||x>panelW||y<25||y>panelH)return false;if(pending)return true;if(x>=rightX&&y<80){turn(dy>0?-1:1);return true;}if(x>=rightX&&x<rightX+117){objectiveScroll+=dy>0?-1:1;return true;}if(x<125){selected=Math.clamp(selected+(dy>0?-1:1),0,3);page=objectiveScroll=0;notice="";refresh();return true;}return super.mouseScrolled(mx,my,dx,dy);}
 @Override public boolean keyPressed(int key,int scan,int mods){if(key==262||key==263){turn(key==262?1:-1);return true;}return super.keyPressed(key,scan,mods);}
 @Override public boolean isPauseScreen(){return false;}
 private final class ActionButton extends Button {private final boolean primary;ActionButton(int x,int y,int w,String label,int action){super(x,y,w,18,t("button."+label),btn->{if(action==-1)onClose();else if(action>=0)send(action);},DEFAULT_NARRATION);primary=action==2;}
  @Override protected void renderWidget(GuiGraphics g,int mx,int my,float delta){image(g,"button",getX(),getY(),getWidth(),18,32,32);if(primary&&active)g.fill(getX()+1,getY()+1,getX()+getWidth()-1,getY()+17,0x6045623E);if(isHoveredOrFocused()&&active)g.renderOutline(getX(),getY(),getWidth(),18,0xFFB9A16C);g.drawCenteredString(font,getMessage(),getX()+getWidth()/2,getY()+5,!active?0x888888:primary?0x91AA88:0xDDD0AD);}
 }
 private final class Row extends Button {private final int index;Row(int x,int y,int w,int h,int i){super(x,y,w,h,t("title."+i),b->{selected=i;page=objectiveScroll=0;notice="";refresh();minecraft.getSoundManager().play(net.minecraft.client.resources.sounds.SimpleSoundInstance.forUI(org.slavicmyths.finist.FinistSounds.get("quest_select"),1,.35F));},DEFAULT_NARRATION);index=i;}
  @Override protected void renderWidget(GuiGraphics g,int mx,int my,float delta){String state=data.getList("Quests",10).getCompound(index).getString("State");boolean locked=state.startsWith("LOCKED");image(g,"quest_row",getX(),getY(),104,30,32,32);if(selected==index)g.fill(getX()+1,getY()+1,getX()+103,getY()+29,0x80464A51);if(selected==index||isHoveredOrFocused())g.renderOutline(getX(),getY(),104,30,0xFFB9A16C);image(g,"quest_"+index,getX()+3,getY()+5,18,18,32,32);lines(g,t("title."+index),getX()+25,getY()+2,76,2,locked?0x888888:0xDDD0AD);g.drawString(font,t("state."+state.toLowerCase()),getX()+25,getY()+21,locked?0x888888:state.equals("REWARD_READY")||state.equals("COMPLETED")?0x91AA88:0xB9A16C,false);}
 }
}
